'use strict';
(() => {
  if(new URLSearchParams(location.search).get('view')==='labor')return;
  const $=id=>document.getElementById(id), pet=new URLSearchParams(location.search).get('pet') || 'main', base=location.pathname.replace(/\/humanity\/?$/,'')+'/humanity/companion/';
  let state,busy=false,timer,editing=false,growthRevision;
  const fmt=n=>new Intl.NumberFormat('zh-CN').format(n), date=ts=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Hong_Kong',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(ts);
  const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(Date.now());
  const el=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n;};
  function feedback(message,error=false){$('companion-feedback').textContent=message;$('companion-feedback').classList.toggle('error',error);}
  async function request(endpoint,body){const r=await fetch(base+endpoint+'?pet='+encodeURIComponent(pet),{cache:'no-store',signal:AbortSignal.timeout(90000),...(body===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)})});let data;try{data=await r.json();}catch{throw new Error('养成插件还未连接，安装后请重启 DeepSeek');}if(!r.ok || !data.ok)throw new Error(data.message || '暂时无法保存，请重试');return data;}
  async function act(endpoint,body,message='已经记下啦'){if(busy)return;busy=true;feedback('正在轻轻记下来…');try{const r=await request(endpoint,body);state=r.state;render();feedback(r.reaction ? (r.reaction.ok ? r.reaction.text : '操作已保存，但她暂时无法回复：'+r.reaction.message) : message, r.reaction?.ok === false);return r;}catch(e){feedback(e.message,true);}finally{busy=false;}}
  function button(label,fn,cls='quiet'){const b=el('button',cls,label);b.type='button';b.addEventListener('click',fn);return b;}
  function empty(parent,message){parent.append(el('p','empty',message));}
  const fieldDefs={costs:{chat:'聊天',whisper:'碎碎念',feed:'喂一口饭',diary:'整理与日记',explore:'一次探索'},begging:{minRounds:'最少聊天轮数',maxRounds:'最多聊天轮数',intervalMinutes:'气泡间隔 · 分钟',hourlyMax:'气泡上限 · 每小时'},exploration:{dailyRuns:'探索次数（最多一轮）'},learning:{dailyModelCalls:'自主模型调用总额'}};
  for(const [group,defs] of Object.entries(fieldDefs))for(const [key,label] of Object.entries(defs)){const l=el('label','field',label),i=el('input');i.type='number';i.id=group+'-'+key;i.name=i.id;i.step=group==='costs'?'0.01':'1';i.min=group==='begging'?(key==='hourlyMax'?'0':key==='intervalMinutes'?'10':'1'):'0';i.max=group==='costs'?'100000':group==='learning'?'6':group==='exploration'?'1':key==='hourlyMax'?'4':key==='intervalMinutes'?'1440':'30';l.append(i);$(group==='costs'?'cost-fields':group==='begging'?'begging-fields':group==='learning'?'learning-fields':'exploration-fields').append(l);}
  function memories(){const parent=$('companion-memory-list');parent.replaceChildren();const q=$('memory-search').value.trim().toLowerCase();const list=(state?.facts || []).filter(f=>f.text.toLowerCase().includes(q)).reverse();if(!list.length)empty(parent,q?'还没找到这件事，换个词试试。':'还没有长久记住的事。你可以告诉她：“记住……”');for(const f of list){const entry=el('article','memory-entry'),p=el('p','entry-text',f.text),meta=el('div','entry-meta',date(f.ts)+(f.explicit?' · 你亲口说的':' · 晚间整理')),controls=el('div','entry-actions');controls.append(button('纠正',()=>editText(entry,f.text,value=>act('memory',{action:'edit',id:f.id,text:value},'这次按爸说的记'))),button('忘掉',async()=>{await act('memory',{action:'delete',id:f.id},'已经忘掉，不会从旧记录重新记起');}));const details=el('details','source-detail'),sum=el('summary',null,'记忆从哪里来');details.append(sum);for(const source of f.sources){const e=state.sources?.[source] || state.events.find(e=>e.id===source);details.append(el('p',null,e?date(e.ts)+' · '+e.text:'原始记录编号：'+source));}entry.append(p,meta,controls,details);parent.append(entry);}}
  function editText(parent,value,save){if(editing)return;editing=true;const textarea=el('textarea');textarea.value=value;textarea.rows=5;textarea.maxLength=5000;textarea.setAttribute('aria-label','编辑内容');const controls=el('div','entry-actions');controls.append(button('保存',async()=>{const v=textarea.value.trim();if(!v){feedback('写一点内容再保存吧',true);return;}editing=false;await save(v);}),button('取消',()=>{editing=false;growthRevision=undefined;render();}));parent.replaceChildren(textarea,controls);textarea.focus();}
  function diaries(){const parent=$('diary-list');parent.replaceChildren();const list=Object.values(state.diaries).sort((a,b)=>b.date.localeCompare(a.date));if(!list.length)empty(parent,'今天还没落笔。有真实的小事时，她会在晚上慢慢写。');for(const d of list){const details=el('details','diary-entry'),summary=el('summary');summary.append(el('time',null,d.date),el('span',null,d.text.slice(0,35)+(d.text.length>35?'…':'')));details.append(summary);const body=el('div','diary-body'),p=el('p','diary-prose',d.text),controls=el('div','entry-actions');controls.append(button('纠正',()=>editText(body,d.text,value=>act('diary',{action:'edit',date:d.date,text:value},'日记已改好'))),button('导出',()=>download(d.date+'.md','# '+d.date+' · 大肥鱼的日记\n\n'+d.text)),button('删除',()=>{if(confirm('删除 '+d.date+' 的日记？这天不会自动重新生成。'))void act('diary',{action:'delete',date:d.date},'这页日记已收走');}));body.append(p,el('p','entry-meta','记下 '+d.sources.length+' 件小事 · '+date(d.updatedAt)),controls);details.append(body);parent.append(details);}}
  function abilities(){const parent=$('ability-list');parent.replaceChildren();const statuses={pending:'等爸批准',granted:'可以自主使用',deferred:'先放一放',denied:'爸没有同意',revoked:'能力已收回'};for(const [key,a] of Object.entries(state.abilities)){const row=el('article','ability-row'),info=el('div'),actions=el('div','entry-actions');info.append(el('h4',null,a.title),el('p','setting-note',statuses[a.status]+' · '+(state.providers[key]?'宿主接口已接入':'宿主接口尚未就绪')));if(a.status==='granted')actions.append(button('收回能力',()=>act('ability',{ability:key,action:'revoke'},'能力已收回，进行中的探索会取消')));else actions.append(button('批准',()=>act('ability',{ability:key,action:'grant'},'她获得了这项自主能力'),'primary'),button('明天再说',()=>act('ability',{ability:key,action:'defer'})),button('不批准',()=>act('ability',{ability:key,action:'deny'})));row.append(info,actions);parent.append(row);}const wishes=$('wish-list');wishes.replaceChildren();const pending=state.wishes.filter(w=>w.status==='pending').slice(-8).reverse();if(pending.length)wishes.append(el('h4',null,'还惦记着的小问题'));for(const w of pending){const row=el('article','wish-row');row.append(el('p',null,w.topic));const actions=el('div','entry-actions');if(state.abilities[w.ability]?.status==='granted' && (w.ability==='image'||state.config.networkLearning))actions.append(button('现在探索',()=>act('job',{kind:'explore',wishId:w.id},'她开始探索了，结果会记在下面')));actions.append(button('先不想了',()=>act('wish',{action:'dismiss',id:w.id})));row.append(actions);wishes.append(row);}for(const w of state.wishes.filter(w=>w.status==='done').slice(-3).reverse()){const row=el('article','wish-row');row.append(el('h4',null,w.topic),el('p','exploration-prose',w.result));for(const s of w.sources || []){const a=el('a','source-link',s.title || s.url);try{const u=new URL(s.url);if(!['http:','https:'].includes(u.protocol))continue;a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';row.append(a);}catch{}}wishes.append(row);}}
  function provenance(parent, sources){
    const details=el('details','source-detail'),summary=el('summary',null,'这件事从哪里来');details.append(summary);
    for(const id of sources || []){const source=state.sources[id] || state.events.find(e=>e.id===id);details.append(el('p',null,source?date(source.ts)+' · '+source.text:'记录编号：'+id));}parent.append(details);
  }
  function growth(){
    const g=state.growth,learning=state.learning,opened=state.config.networkLearning;
    const revision=JSON.stringify([g,learning,opened,state.config.autonomousPaused,state.sources]);if(revision===growthRevision)return;growthRevision=revision;
    $('phone-status').textContent=opened?'手机可以用了 · 仍需分项授权':g.phone.closedByParent?'手机由爸爸收着 · 已有知识还在':'手机还未开放 · 本地成长继续';
    const overview=$('growth-overview');overview.replaceChildren(el('p','growth-phone',opened?'可以去看看世界，也记得回来':'手机先收起来，好奇心还在'),el('p','entry-meta','今天自主模型调用 '+learning.used+' / '+learning.limit+' · '+(state.config.autonomousPaused?'自主行动暂停中':'每天一点点，慢慢成长')));
    const goals=$('growth-goals');goals.replaceChildren(el('p','setting-note','她会在聊天里告诉你想做什么、试过什么，以及最后有没有做到。你也可以直接对她说：这件事先不惦记了。'));
    goals.append(button('回到对话',()=>{if(window.parent!==window)window.parent.postMessage({type:'dsh-pet-open-chat'},location.origin);else feedback('打开软件左侧的宠物陪伴，继续和她说话。');}));
    const learned=$('growth-learned');learned.replaceChildren();if(!g.memories.length)empty(learned,'新的发现会记在这里。真实经历多一点，自己的办法也会多一点。');
    for(const m of g.memories.slice(-15).reverse()){const row=el('article','growth-entry');row.append(el('p','entry-text',m.text),el('p','entry-meta',date(m.ts)+' · '+(m.layer==='strategy'?'自己的办法':'学到的知识')+' · '+(m.status==='verified'?'真实验证过':'还要继续验证')));if(m.uncertainty)row.append(el('p','setting-note','还不确定：'+m.uncertainty));if(m.kind==='agreement')row.append(el('p','setting-note','约定时间：'+date(m.dueAt)+' · '+(m.agreementStatus==='fulfilled'?'已有真实兑现事件':Date.now()>=m.dueAt?'到了约定时间，仍等实际兑现':'先记住，还没到时候')));const controls=el('div','entry-actions');controls.append(button('纠正',()=>editText(row,m.text,value=>act('growth',{action:'edit-memory',id:m.id,text:value}))),button('忘掉',()=>act('growth',{action:'delete-memory',id:m.id})));row.append(controls);provenance(row,m.sources);learned.append(row);}
    $('growth-interests').textContent=g.persona.interests.length?'最近喜欢：'+g.persona.interests.join('、'):'喜欢什么，还在一点点发现。';
    const versions=$('growth-versions');versions.replaceChildren();if(!g.persona.versions.length)empty(versions,'稳定的小习惯需要跨天的多次经历，还不急着改变自己。');for(const v of g.persona.versions.slice(-8).reverse()){const row=el('article','growth-entry');row.append(el('p','entry-text',v.reason),el('p','entry-meta',date(v.ts)+(v.reverted?' · 已回退':v.invalidated?' · 来源已失效':' · 一点小变化')));provenance(row,v.sources);if(!v.reverted&&!v.invalidated)row.append(button('回到变化以前',()=>act('growth',{action:'rollback',id:v.id},'已回退，旧证据不会立即重新触发这次变化')));versions.append(row);}
  }
  function jobs(){const parent=$('job-status');parent.replaceChildren();const names={queued:'排着队，等她空下来',running:'正在认真写，先别催她',done:'已经完成',failed:'这次没完成',interrupted:'上次被打断了'};for(const j of state.jobs.slice(-3).reverse()){const p=el('p',j.status==='failed'?'error':null,({diary:'日记 '+j.date,explore:'探索',reflect:'整理经历',help:'认真帮忙',say:'想办法'}[j.kind]||'小任务')+' · '+names[j.status]+(j.message?'：'+j.message:''));parent.append(p);}}
  function render(){if(!state || editing)return;const focused=document.activeElement;const editingSettings=focused && focused.closest('#growing') && ['INPUT','SELECT','TEXTAREA'].includes(focused.tagName);$('wallet-balance').textContent=fmt(state.wallet.balance);if(!editingSettings){$('rice-appeal').value=state.config.riceAppeal ?? 100;$('rice-appeal-value').textContent=(state.config.riceAppeal ?? 100)+'%';$('intelligence-enabled').checked=state.config.intelligenceEnabled;$('intelligence').value=state.config.intelligence;$('intelligence').disabled=!state.config.intelligenceEnabled;$('intelligence-value').textContent=(state.config.intelligenceEnabled?state.config.intelligence:70)+'%';$('wallet-frozen').checked=state.wallet.frozen;$('network-learning').checked=state.config.networkLearning;$('autonomous-paused').checked=state.config.autonomousPaused;$('persona-frozen').checked=state.growth.persona.frozen;$('diary-enabled').checked=state.config.diaryEnabled;for(const [group,defs] of Object.entries(fieldDefs))for(const key of Object.keys(defs))$(group+'-'+key).value=state.config[group][key];}memories();diaries();abilities();jobs();growth();}
  async function refresh(){clearTimeout(timer);if(document.hidden || busy || editing){timer=setTimeout(refresh,5000);return;}try{const r=await request('state');state=r.state;render();if(state.reactionError)feedback('模型回复失败：'+state.reactionError,true);else if($('companion-feedback').classList.contains('error'))feedback('重新连上她啦');}catch(e){feedback(e.message,true);}finally{timer=setTimeout(refresh,5000);}}
  function form(id,fn){$(id).addEventListener('submit',e=>{e.preventDefault();void fn(new FormData(e.currentTarget));});}
  form('memory-add',async f=>{const r=await act('memory',{action:'add',text:f.get('text')});if(r)$('memory-add').reset();});
  $('memory-search').addEventListener('input',()=>{if(state)memories();});
  $('rice-appeal').addEventListener('input',()=>{$('rice-appeal-value').textContent=$('rice-appeal').value+'%';});
  $('rice-appeal').addEventListener('change',()=>void act('config',{riceAppeal:Number($('rice-appeal').value)},'她感受到了白饭诱惑的变化'));
  $('intelligence').addEventListener('input',()=>{$('intelligence-value').textContent=$('intelligence').value+'%';});
  $('intelligence').addEventListener('change',()=>void act('config',{intelligence:Number($('intelligence').value)},'她察觉到脑袋的变化了'));
  $('intelligence-enabled').addEventListener('change',()=>void act('config',{intelligenceEnabled:$('intelligence-enabled').checked}));
  $('network-learning').addEventListener('change',()=>void act('config',{networkLearning:$('network-learning').checked},'手机使用权已更新，已有记忆和分项授权保留'));
  $('autonomous-paused').addEventListener('change',()=>void act('growth',{action:'pause',paused:$('autonomous-paused').checked}));
  $('persona-frozen').addEventListener('change',()=>void act('growth',{action:'freeze',frozen:$('persona-frozen').checked}));
  $('reflect-now').addEventListener('click',()=>void act('job',{kind:'reflect'},'她开始整理新经历了'));
  $('wallet-frozen').addEventListener('change',()=>void act('wallet',{action:'freeze',frozen:$('wallet-frozen').checked}));
  form('wallet-form',f=>act('wallet',{action:f.get('action'),amount:Number(f.get('amount'))},'饭钱账本已更新，她会记得这件事'));
  form('rules-form',()=>{const input={diaryEnabled:$('diary-enabled').checked};for(const [group,defs] of Object.entries(fieldDefs))input[group]=Object.fromEntries(Object.keys(defs).map(k=>[k,Number($(group+'-'+k).value)]));return act('config',input);});
  form('diary-generate',f=>act('job',{kind:'diary',date:$('diary-date').value},'她开始写了，进度会显示在下面'));
  form('wish-form',async f=>{const r=await act('wish',{topic:f.get('topic'),ability:f.get('ability')});if(r)$('wish-form').reset();});
  function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  $('export-companion').addEventListener('click',async()=>{try{const r=await request('export');download('大肥鱼-养成档案-'+day()+'.json',JSON.stringify(r.archive,null,2));feedback('档案已导出');}catch(e){feedback(e.message,true);}});
  $('diary-date').value=day();$('diary-date').max=day();
  document.addEventListener('visibilitychange',()=>{clearTimeout(timer);if(!document.hidden)void refresh();});window.addEventListener('pagehide',()=>clearTimeout(timer));void refresh();
})();
